if(args.Length==0||args[0] is "--help" or "-h"){Console.WriteLine("bogmem - parity harness\n\nCommands:\n  parity [module] [--report path]\n  --help");return 0;}
if(args[0]=="parity"){var module=args.Length>1&&!args[1].StartsWith('-')?args[1]:"config";var report=args.Skip(1).SkipWhile(x=>x!="--report").Skip(1).FirstOrDefault()??"parity_report.json";var result=ParityRunner.Run(Directory.GetCurrentDirectory(),module,report);Console.WriteLine($"parity {module}: {(result.Passed?"passed":"failed")} ({result.CheckedCount} checks); report={report}");return result.Passed?0:1;}
Console.Error.WriteLine($"Unknown command '{args[0]}'. Use --help.");return 2;
